update public.learning_paths
set
  title = 'Drawing I (Foundation Year)',
  goal = 'Drawing I (Foundation Year)',
  summary = 'Drawing I is a foundation-year studio course that builds disciplined observation, line control, value, light, perspective, gesture, figure structure, composition, sketchbook practice, and critique habits. The course treats drawing as a way of seeing, thinking, researching, experimenting, and communicating across fine arts, design, illustration, architecture, and contemporary studio practice.',
  data = $dr1json${"slug": "drawing-i-foundation-year", "title": "Drawing I (Foundation Year)", "description": "Drawing I is a foundation-year studio course that builds disciplined observation, line control, value, light, perspective, gesture, figure structure, composition, sketchbook practice, and critique habits. The course treats drawing as a way of seeing, thinking, researching, experimenting, and communicating across fine arts, design, illustration, architecture, and contemporary studio practice.", "topics": [{"id": "168aab50-85de-4195-8e35-62b0402e37bb", "type": "topic", "title": "Studio Culture, Materials, Tools, and Drawing Habits", "description": "Foundation drawing begins with disciplined studio habits. Students learn how materials behave, how to set up a workspace, and how regular practice turns observation into skill.", "children": [{"id": "77bf2f79-12e5-48a8-adbc-7dd1d7cd530e", "type": "subtopic", "title": "Drawing materials and surfaces", "children": [{"id": "b9c37d4e-73da-4569-ac4a-dbc48c7da1d5", "type": "concept", "title": "Graphite, charcoal, conte, ink, eraser, and blending tools"}, {"id": "63d080ca-f7e7-4b04-a19a-90549e5ac217", "type": "concept", "title": "Newsprint, drawing paper, toned paper, and sketchbooks"}, {"id": "8a10d326-28cf-4bb1-917d-3f0c24b84f43", "type": "concept", "title": "Fixative, storage, cleanup, and studio safety"}], "description": "Students learn what different tools do and why tool choice affects mark, value, speed, and revision."}, {"id": "3766b009-71f7-4271-aec7-9818d1922053", "type": "subtopic", "title": "Studio process and practice rhythm", "children": [{"id": "5eec6dcd-3cf3-4448-92ee-25b07eee8dca", "type": "concept", "title": "Warmups, timed studies, and daily pages"}, {"id": "c871378d-3a05-4669-893a-b88e759f8fe4", "type": "concept", "title": "Set-up, lighting, posture, and easel use"}, {"id": "a4ae7914-c264-4b03-a6bb-b3f6ca8d11de", "type": "concept", "title": "Process notes, dates, and reflection"}], "description": "This subtopic builds reliable habits for showing up, warming up, and sustaining attention."}, {"id": "0efe386a-01b2-4e40-84b6-ee94eec35c56", "type": "subtopic", "title": "Foundation critique norms", "children": [{"id": "a6df54d8-4b8e-489e-95cf-55f7e7d71679", "type": "concept", "title": "Describe before judging"}, {"id": "3fc3aae3-d970-40ac-9a3f-7977676351ac", "type": "concept", "title": "Intent, effect, and evidence"}, {"id": "19a0a251-67b9-4a2c-a88c-d0687c4a289b", "type": "concept", "title": "Receiving feedback and setting revision goals"}], "description": "Students learn how to talk about drawings with specificity and care."}]}, {"id": "23cf3ef4-c2e1-446e-b6d0-658a8f4621a4", "type": "topic", "title": "Seeing, Measuring, and Observational Discipline", "description": "Drawing I is mainly about learning to see. Students practice slowing down, comparing, measuring, and correcting what they think they see against what is actually present.", "children": [{"id": "74a53073-acd0-4490-9ae1-290e53031810", "type": "subtopic", "title": "Perceptual observation", "children": [{"id": "31b03ae4-3a51-4c02-b337-cd8dbf213ecf", "type": "concept", "title": "Edges, angles, intervals, and alignments"}, {"id": "a2ede1f3-03a1-4c1b-ba87-68a8f46f939b", "type": "concept", "title": "Negative space and shape relationships"}, {"id": "3a9523b3-b498-4993-bdf7-f8fdde9760aa", "type": "concept", "title": "Visual checking and self-correction"}], "description": "Students learn to suspend symbolic shortcuts and attend to actual visual relationships."}, {"id": "d672b6e6-6435-4405-b2cb-efd9a832a9e9", "type": "subtopic", "title": "Sighting and proportion", "children": [{"id": "378a833f-2a80-48bb-a592-ad6173904017", "type": "concept", "title": "Plumb lines and level lines"}, {"id": "61bb2c0c-0621-4b30-905b-9f628f554ab9", "type": "concept", "title": "Comparative measurement"}, {"id": "6eae00f6-451f-44c3-9643-06a07149bae3", "type": "concept", "title": "Proportion, scale, and relational drawing"}], "description": "This subtopic teaches practical measuring methods that support accurate observation."}, {"id": "d5180ea7-9dc8-49a8-9c32-c9c71ed3e76e", "type": "subtopic", "title": "Drawing from simple objects", "children": [{"id": "8e15c28b-22e0-42d3-9156-a06e4c6b2938", "type": "concept", "title": "Boxes, cylinders, spheres, and organic forms"}, {"id": "df2bbdd7-93ca-4b93-8bf4-8dbd70b29aeb", "type": "concept", "title": "Object placement and eye level"}, {"id": "d6ff132e-b9a0-4106-8831-63505f90f3ca", "type": "concept", "title": "Simple-to-complex observation sequences"}], "description": "Students build accuracy through still-life structures before moving to complex subjects."}]}, {"id": "5096e4a7-a95c-48c9-86da-cc8bf5c61e6e", "type": "topic", "title": "Line Quality, Contour, and Edge", "description": "Line is both a record of looking and a design element. Students learn to use line with confidence, sensitivity, hierarchy, and expressive control.", "children": [{"id": "2d15213d-60db-440a-b3e5-6b81232d14b9", "type": "subtopic", "title": "Line control", "children": [{"id": "01fd48c1-5616-4bd9-bc11-113c18109883", "type": "concept", "title": "Straight, curved, tapered, and weighted lines"}, {"id": "6aabd05f-0585-4a3f-9e86-21a5b62eaf2c", "type": "concept", "title": "Speed, pressure, rhythm, and confidence"}, {"id": "f6695390-e4a3-4c84-9948-8a89615fecdb", "type": "concept", "title": "Ghosting, overhand grip, and arm movement"}], "description": "Students develop physical control through repeated marks and varied pressure."}, {"id": "d001d63b-e7aa-4f01-8a0f-383cf68489bd", "type": "subtopic", "title": "Contour drawing", "children": [{"id": "17af105d-7da5-48c2-8b5a-d2f7684281aa", "type": "concept", "title": "Blind contour"}, {"id": "bcd18bd9-7ef8-4a79-91b6-d98b620bfb18", "type": "concept", "title": "Modified contour"}, {"id": "c1a31539-a24b-443c-944f-2c3b001d1fb5", "type": "concept", "title": "Cross-contour and form wrapping"}], "description": "Contour studies teach students to follow edges carefully and coordinate hand, eye, and attention."}, {"id": "cf30046b-b4b1-4f1c-ac58-64a9f61397d6", "type": "subtopic", "title": "Edge hierarchy", "children": [{"id": "ce8647d5-f969-4072-87c2-391baae72883", "type": "concept", "title": "Line weight and spatial depth"}, {"id": "793a133e-651a-40b7-8d25-ce6899b52a16", "type": "concept", "title": "Overlaps and contact points"}, {"id": "4b9765b6-5e6d-4d44-9966-f624d6f0e43d", "type": "concept", "title": "Edges as design and emphasis"}], "description": "Students learn that edges can be hard, soft, lost, found, light, heavy, active, or quiet."}]}, {"id": "e8591a49-0771-41fa-88f5-461244eb0754", "type": "topic", "title": "Shape, Negative Space, and Notan", "description": "Before form becomes convincing, shape must be organized clearly. This topic teaches students to see silhouettes, intervals, and value masses as design structures.", "children": [{"id": "6a96e011-e072-40b5-9718-e51e2f17728c", "type": "subtopic", "title": "Positive and negative shapes", "children": [{"id": "f667248b-ea3f-42b3-ad6d-77803a1f98d1", "type": "concept", "title": "Figure-ground relationships"}, {"id": "10567bc8-916e-4186-bbd6-eca7752fb696", "type": "concept", "title": "Interior negative spaces"}, {"id": "e3e8ed41-40a7-487d-86b4-b6ee8042c0ba", "type": "concept", "title": "Shape mapping and simplification"}], "description": "Students use negative space to correct proportion and discover abstract structure."}, {"id": "fee9e8be-f50b-4619-a668-f35ca9743330", "type": "subtopic", "title": "Notan and value grouping", "children": [{"id": "874f39e4-1ba2-45b5-bacd-96a51781ac20", "type": "concept", "title": "Two-value and three-value studies"}, {"id": "c696d103-6bb5-48e0-bfe2-a4af82a30d10", "type": "concept", "title": "Shape clarity and pattern"}, {"id": "84fb3d5f-9c65-43ad-aab8-0576ec5ad7a9", "type": "concept", "title": "Thumbnail value planning"}], "description": "This subtopic teaches students to organize drawings through large light and dark masses."}, {"id": "e2426e79-f5c4-4ddf-8c8b-ba9b129baf6d", "type": "subtopic", "title": "Composition through shape", "children": [{"id": "113d9c75-6a54-4563-a8a7-0df3fbf25cf7", "type": "concept", "title": "Cropping and margins"}, {"id": "0a0f8cd7-1c82-4bf2-8164-306dc19d461a", "type": "concept", "title": "Balance, tension, and asymmetry"}, {"id": "4b799aa6-0b7a-4bd9-ba8c-bd171670acb3", "type": "concept", "title": "Focal area and visual path"}], "description": "Students learn to place forms intentionally within the page."}]}, {"id": "9d55162f-6be2-4247-a844-ef2f74e8a3c4", "type": "topic", "title": "Tone, Value, and Shading Systems", "description": "Value gives drawings light, mood, structure, and depth. Students learn to build value scales, control transitions, and separate local value from light effect.", "children": [{"id": "a2d397ff-bcda-4a3e-80a9-ea7f1bc0e830", "type": "subtopic", "title": "Value scales and range", "children": [{"id": "abbb9071-1e1a-45df-b462-90d1d4183379", "type": "concept", "title": "Value scales and swatches"}, {"id": "c881041f-1a77-4a08-b03d-f5f4469cb026", "type": "concept", "title": "Local value versus light value"}, {"id": "3dd6a940-5896-4ffd-b239-73d10b01d5f6", "type": "concept", "title": "High key, low key, and full range"}], "description": "Students build control over light, middle, and dark values."}, {"id": "d6af667d-d10e-4741-ab33-fec27af07620", "type": "subtopic", "title": "Mark-based shading", "children": [{"id": "91eeeb84-8bea-43ee-a94f-8f3ea6103d3b", "type": "concept", "title": "Hatching, cross-hatching, stippling, and scumbling"}, {"id": "4c1263ab-b642-43a0-b391-174336d1159f", "type": "concept", "title": "Blending versus visible marks"}, {"id": "75c3fe81-84f1-4f40-b606-d6d66be9f219", "type": "concept", "title": "Direction, rhythm, and surface"}], "description": "This subtopic explores different ways marks create tone and texture."}, {"id": "dadf7e2b-51af-4d9a-9258-429aecb64e5b", "type": "subtopic", "title": "Value structure in drawings", "children": [{"id": "fdbf14f2-7fd9-472d-a6c6-a2fa1b0268f3", "type": "concept", "title": "Grouping shadows"}, {"id": "49101e1b-b434-4bf9-b8cc-dc4fe3adca5d", "type": "concept", "title": "Separating planes"}, {"id": "dceb82f4-aabb-4d0c-9bf5-178e87943dc2", "type": "concept", "title": "Controlling emphasis through contrast"}], "description": "Students learn to use value as an organizing system rather than surface decoration."}]}, {"id": "d81f0fe0-18c2-4acd-8640-1eb8c0714407", "type": "topic", "title": "Light, Shadow, and Form", "description": "Light reveals form. Students learn how illumination, shadow, reflected light, and plane changes make objects feel three-dimensional.", "children": [{"id": "93b0c400-4d0b-4fb5-8f1d-8e71cdc25669", "type": "subtopic", "title": "Light logic", "children": [{"id": "3e17a21c-dd49-4a5e-b536-8e13fc27e58c", "type": "concept", "title": "Light source, highlight, halftone, core shadow, reflected light"}, {"id": "a27aac01-1c08-4916-971c-9b7844326dba", "type": "concept", "title": "Cast shadow and occlusion shadow"}, {"id": "61e01f88-17ef-49ba-8248-df56f8407275", "type": "concept", "title": "Terminator and form turning"}], "description": "Students learn the predictable behavior of light across simple forms."}, {"id": "69081333-0eed-4888-aad0-dfa0850c490a", "type": "subtopic", "title": "Drawing geometric solids", "children": [{"id": "301b5d74-61a0-4265-b52c-e32614bcc204", "type": "concept", "title": "Planes and gradients"}, {"id": "7ba2849e-213a-4fcb-810b-13adf64ee9b4", "type": "concept", "title": "Ellipses and cylindrical volume"}, {"id": "3a995e2e-7a4a-4b6f-b6ec-7d4120411bf4", "type": "concept", "title": "Shadow construction and edge control"}], "description": "This subtopic turns spheres, cylinders, cones, and boxes into training grounds for form."}, {"id": "4d1201bd-7ea8-4167-99d8-4efc81bb5763", "type": "subtopic", "title": "Form in complex objects", "children": [{"id": "814f20ce-85e0-44b6-8ff4-0296bfaae078", "type": "concept", "title": "Breaking complex forms into masses"}, {"id": "af12200e-85db-4149-9e7b-105d2c373bb0", "type": "concept", "title": "Surface direction and plane change"}, {"id": "e47eb889-d3f8-4a5e-ac0c-da703a40f7f3", "type": "concept", "title": "Selective detail and finish"}], "description": "Students transfer light logic from simple solids to still life and figure."}]}, {"id": "b673cc27-e8e0-4ee1-80f6-82f75aed218b", "type": "topic", "title": "Perspective and Spatial Construction", "description": "Perspective helps students understand space, not just copy appearances. Students learn to build convincing depth from observation and imagination.", "children": [{"id": "acca9f6c-6d93-49d1-9220-a27f363981b5", "type": "subtopic", "title": "Linear perspective foundations", "children": [{"id": "d61f58fb-373f-4915-bea4-53d420d90279", "type": "concept", "title": "Horizon line and eye level"}, {"id": "f28fe3b9-4afc-4767-a545-6e09a1387a1c", "type": "concept", "title": "One-point, two-point, and three-point perspective"}, {"id": "14a0fc91-c30c-4034-9ce8-90dd472b88a3", "type": "concept", "title": "Convergence, scale, and station point"}], "description": "Students learn the basic systems that organize depth on a flat page."}, {"id": "a8543c61-1efd-4be6-835c-7ed72f378030", "type": "subtopic", "title": "Boxes, ellipses, and constructed forms", "children": [{"id": "857b1e5d-e419-49ae-8fb2-2d15ba79ab32", "type": "concept", "title": "Rotated boxes and subdivisions"}, {"id": "6cd15dd5-a797-4e9a-ba4b-3432022c864f", "type": "concept", "title": "Ellipses in perspective"}, {"id": "1ee331d2-90f8-42a8-a076-3e1df4652334", "type": "concept", "title": "Cylinders, wheels, and rounded forms"}], "description": "This subtopic connects perspective to practical drawing problems."}, {"id": "5e4f0b30-9fa8-4087-90a1-20f5633446ec", "type": "subtopic", "title": "Interior and exterior space", "children": [{"id": "630ffe37-aca6-41f2-a052-8e800fb2b4fe", "type": "concept", "title": "Measuring depth and height"}, {"id": "29ea5ef2-e53a-4a4b-a5b3-e0665a95c8a9", "type": "concept", "title": "Overlapping forms and atmospheric cues"}, {"id": "2fed4f62-844b-4590-908b-99d3345ebd4c", "type": "concept", "title": "Combining observation with construction"}], "description": "Students apply perspective to rooms, street views, and built environments."}]}, {"id": "0e4e711b-4fe5-41df-95e5-5c9fce6ff7be", "type": "topic", "title": "Drawing from Life: Still Life, Objects, and Space", "description": "Drawing from life trains sustained attention. Students learn to compose, observe, revise, and finish drawings from arranged objects and real spaces.", "children": [{"id": "3b658f49-5423-4f3c-8431-54bb91f5aff4", "type": "subtopic", "title": "Still-life construction", "children": [{"id": "40b149ce-8e05-4cb1-badf-6de569422bdf", "type": "concept", "title": "Set-up, lighting, and viewpoint"}, {"id": "42c64a50-cc76-4485-9093-1c271fea0bed", "type": "concept", "title": "Blocking in and proportion checks"}, {"id": "e48e59ab-19b3-4a2a-b367-c8e45e8c3917", "type": "concept", "title": "Objects as forms, textures, and meanings"}], "description": "Students learn to organize objects into clear spatial and compositional relationships."}, {"id": "f7fc5fab-138e-4058-9475-86034e022902", "type": "subtopic", "title": "Spatial relationships", "children": [{"id": "2f6ac99e-8cbb-4c97-a96e-a66dd89f6da7", "type": "concept", "title": "Ground plane and contact shadows"}, {"id": "eaf3271b-3f17-46cb-8ce1-847f4271cac3", "type": "concept", "title": "Scale relationships and overlap"}, {"id": "08837e90-092b-484b-9deb-40c38c82ba84", "type": "concept", "title": "Foreground, middle ground, and background"}], "description": "This subtopic teaches students to make objects sit together convincingly in space."}, {"id": "cea7e21f-da30-4971-a985-86df072be37e", "type": "subtopic", "title": "Long-study development", "children": [{"id": "46a42263-3d2a-4619-b4f3-485a3466f4c3", "type": "concept", "title": "Thumbnail, gesture, block-in, correction, value, finish"}, {"id": "ce2c38bd-998d-4d85-8c4e-00990fc66e67", "type": "concept", "title": "Revision checkpoints"}, {"id": "4f411971-ea4f-4c9f-a9a3-c7766d9ff63b", "type": "concept", "title": "Avoiding premature detail"}], "description": "Students learn how a drawing evolves from block-in to finished statement."}]}, {"id": "8883821c-33a0-496f-b3ea-b175f44cb581", "type": "topic", "title": "Gesture, Movement, and Quick Studies", "description": "Gesture drawing builds speed, energy, and whole-form thinking. Students learn to capture action before detail and to make decisive visual choices under time limits.", "children": [{"id": "d142cfab-8766-43c0-a772-49fc9207df44", "type": "subtopic", "title": "Gesture fundamentals", "children": [{"id": "86f906d2-03ba-455c-abe3-72021e03f1fd", "type": "concept", "title": "Line of action"}, {"id": "1994083b-0f8e-4198-930d-0d6ef0ab59ae", "type": "concept", "title": "Weight, balance, and direction"}, {"id": "db9f779e-57d7-4944-8c95-d8fbe438bdfa", "type": "concept", "title": "Big-to-small decision making"}], "description": "Students learn to identify the main action and rhythm of a pose or object."}, {"id": "c1615845-4206-4298-a5d3-4c576588ce8f", "type": "subtopic", "title": "Timed drawing practice", "children": [{"id": "3c0b2b8e-0f98-45fe-a257-7400dd0bfc34", "type": "concept", "title": "Thirty-second, one-minute, and five-minute studies"}, {"id": "39659183-00ff-40f5-9aea-b3a5232ee23e", "type": "concept", "title": "Prioritizing motion over contour"}, {"id": "10ad19a0-28b6-4e96-96d8-4921ab817fa7", "type": "concept", "title": "Iteration and pattern recognition"}], "description": "This subtopic uses short sessions to build confidence and fluency."}, {"id": "1767a7bb-38e8-4542-8ad6-4f5329c544c3", "type": "subtopic", "title": "Gesture beyond the figure", "children": [{"id": "df1a88ed-f461-49a8-aa7f-9d3a47bdcda0", "type": "concept", "title": "Object gesture and tilt"}, {"id": "e5e19deb-a7d3-436f-afc9-d3e526fd0727", "type": "concept", "title": "Landscape and architectural movement"}, {"id": "f68fc7b9-88f1-4b05-82ee-b16d198a16d1", "type": "concept", "title": "Expressive simplification"}], "description": "Students learn that gesture applies to objects, animals, spaces, and compositions."}]}, {"id": "893726db-46f5-4f3e-bdaa-2d577cd61950", "type": "topic", "title": "Figure Drawing Fundamentals", "description": "Introductory figure drawing teaches students to see the body as proportion, action, mass, structure, and expressive presence.", "children": [{"id": "ef2a10b7-cbb4-4764-9e41-ab7c340e6d43", "type": "subtopic", "title": "Proportion and landmarks", "children": [{"id": "f0c92fb9-be00-4101-a370-128fb4dd135c", "type": "concept", "title": "Head units and comparative proportion"}, {"id": "55790e45-7ca2-4854-9633-a07221f1bb64", "type": "concept", "title": "Shoulders, pelvis, rib cage, knees, elbows, and ankles"}, {"id": "b2f27dd4-9578-4f8e-9413-7fc216ab8836", "type": "concept", "title": "Variation, foreshortening, and pose type"}], "description": "Students learn basic proportional systems and visible anatomical landmarks."}, {"id": "9d15205b-d6af-4bd3-96a5-dcb2cb21c1bd", "type": "subtopic", "title": "Figure construction", "children": [{"id": "b9084c58-b17e-4d63-a094-a6b8ddeb7be6", "type": "concept", "title": "Bean, box, cylinder, and mannequin forms"}, {"id": "796751bc-24ac-4372-98cd-024ed7fe034d", "type": "concept", "title": "Rib cage, pelvis, and spine relationship"}, {"id": "73d1cf12-e5aa-4185-891b-b84fd1df47f4", "type": "concept", "title": "Limbs as tapered cylinders and wedges"}], "description": "This subtopic gives students simple forms for building believable bodies."}, {"id": "be870176-30ca-4a14-852b-4363bab5aec1", "type": "subtopic", "title": "Ethics and studio protocols", "children": [{"id": "9c7f666a-965a-4d5c-af39-e6b674cee794", "type": "concept", "title": "Respectful conduct and consent"}, {"id": "aeb031d6-530f-4689-b536-4c13480ac038", "type": "concept", "title": "Model breaks, privacy, and boundaries"}, {"id": "34979f6b-95bd-4d10-b7db-a576151c2108", "type": "concept", "title": "Inclusive approaches to bodies and representation"}], "description": "Students learn professional norms for life drawing environments."}]}, {"id": "1b7fbfea-83f6-4af2-a28e-4306a124a486", "type": "topic", "title": "Basic Anatomy for Artists", "description": "Foundation anatomy gives students just enough structure to draw the figure with clarity without turning the course into memorization.", "children": [{"id": "ec38d2c2-c5f7-4bae-afb6-8dc27dc27fcf", "type": "subtopic", "title": "Skeletal structure", "children": [{"id": "a9aec6bd-673d-4c9c-83a5-8628815b7208", "type": "concept", "title": "Skull, spine, rib cage, pelvis, and limbs"}, {"id": "87eb050d-0aa4-4693-beba-23a7db5e5dec", "type": "concept", "title": "Joints and range of motion"}, {"id": "18ed5529-5489-4e90-9d9b-9b009876ee1e", "type": "concept", "title": "Bony landmarks visible on the body"}], "description": "Students learn how the skeleton creates proportion, gesture, and surface landmarks."}, {"id": "719d7dbb-24f4-4420-872b-6e7b26a229a9", "type": "subtopic", "title": "Major muscle masses", "children": [{"id": "f0200299-294c-4ee8-8eda-d837218bcc05", "type": "concept", "title": "Torso, shoulder, arm, hip, and leg groups"}, {"id": "45902032-ff17-4a98-a6cf-849a04e96e5f", "type": "concept", "title": "Compression, stretch, and overlap"}, {"id": "1f5e9b3a-0205-49cf-8a62-1ce47987eae4", "type": "concept", "title": "Anatomy as form logic"}], "description": "This subtopic introduces simplified muscle groups that affect surface form."}, {"id": "c03dfd2f-17c9-41eb-aa2a-f57e28d5b37c", "type": "subtopic", "title": "Hands, feet, and head basics", "children": [{"id": "ea560f23-c58f-4e61-b6be-4cbebc502413", "type": "concept", "title": "Hand blocks, fingers, and gesture"}, {"id": "df7fdf47-fc28-40d3-831e-920fc6b44a71", "type": "concept", "title": "Foot wedge and arch"}, {"id": "46ab8cc5-ff52-40f7-8092-d991de8c0822", "type": "concept", "title": "Head proportion and planes"}], "description": "Students practice high-challenge areas through simplified construction."}]}, {"id": "0e668861-b39e-431f-91f6-ffeade9f22b8", "type": "topic", "title": "Composition, Design, and Page Organization", "description": "Even observational drawings are designed. Students learn how placement, scale, rhythm, contrast, and hierarchy make drawings visually coherent.", "children": [{"id": "e41261fb-b469-4cc9-964c-00eb32cf68b9", "type": "subtopic", "title": "Compositional planning", "children": [{"id": "b648c21c-eeb5-452e-92df-9ee890b6475d", "type": "concept", "title": "Thumbnail sketches"}, {"id": "0b22051a-da1b-465b-89b3-00004dd746a3", "type": "concept", "title": "Cropping, format, and scale"}, {"id": "aa286785-a7f6-402e-bb1c-7d197e946e18", "type": "concept", "title": "Dominant, subordinate, and accent areas"}], "description": "Students learn to test alternatives before committing to a full drawing."}, {"id": "09217e0f-773c-4e20-aa09-e05bc38529bd", "type": "subtopic", "title": "Design principles", "children": [{"id": "aa7472a4-5d22-4a28-9dba-1ac909329fc5", "type": "concept", "title": "Balance, rhythm, unity, variety, and contrast"}, {"id": "66b5f81d-5a0c-4620-b35b-cdf12142b4ab", "type": "concept", "title": "Repetition and visual movement"}, {"id": "996d3107-98a6-4792-812c-eac49219acc3", "type": "concept", "title": "Hierarchy and focal emphasis"}], "description": "This subtopic connects drawing to broader visual language."}, {"id": "7a731700-b522-499d-bfc4-2d1a41459335", "type": "subtopic", "title": "Critique of composition", "children": [{"id": "d8541a6e-04eb-4f4a-bdf3-c2ad15aca341", "type": "concept", "title": "Value pattern and eye path"}, {"id": "3ddac6c6-76fe-4d00-9abb-aa2b4853244e", "type": "concept", "title": "Tangents, crowding, and awkward spacing"}, {"id": "cecdd642-7d0b-4271-a332-42645d2501d0", "type": "concept", "title": "Revision through recomposition"}], "description": "Students learn to diagnose why a drawing works or fails as an image."}]}, {"id": "7d9bbb12-6168-445c-9842-75d98280245f", "type": "topic", "title": "Texture, Surface, and Material Translation", "description": "Drawing translates touch into sight. Students learn how marks can suggest wood, glass, fabric, metal, skin, stone, paper, and other surfaces.", "children": [{"id": "09829fb9-ed26-4974-877e-7bea70060789", "type": "subtopic", "title": "Texture observation", "children": [{"id": "559482c4-3ee7-4040-8d16-f558c662369f", "type": "concept", "title": "Surface direction and edge behavior"}, {"id": "769937d1-0bb3-4e2a-a5c7-5ebe92afea96", "type": "concept", "title": "Rough, smooth, reflective, matte, soft, and hard surfaces"}, {"id": "5a3fe925-c2eb-4717-8b64-e0fd432651ae", "type": "concept", "title": "Scale of texture marks"}], "description": "Students distinguish texture from decorative pattern and connect texture to form."}, {"id": "66daa672-2ed7-4b7f-9c4b-6a96cacddf9f", "type": "subtopic", "title": "Material-specific mark-making", "children": [{"id": "fb32f2d1-cf83-475e-a49e-7ef444a6775d", "type": "concept", "title": "Charcoal massing and erasure"}, {"id": "8311e0b3-0bd4-41fa-b811-308ce10a342e", "type": "concept", "title": "Graphite layering and burnishing"}, {"id": "a68e11ec-d49b-46b6-94fc-5246b7ab3387", "type": "concept", "title": "Ink line, wash, and economy"}], "description": "This subtopic expands students' technical vocabulary."}, {"id": "eda2cd43-1d2d-410a-b0cb-49ee9a162841", "type": "subtopic", "title": "Drapery and fabric", "children": [{"id": "1fd6d817-3e1e-472a-989d-03e116e7d02a", "type": "concept", "title": "Pipe, zigzag, spiral, and drop folds"}, {"id": "beb9a63c-c5ba-4555-bed9-8580b89f7895", "type": "concept", "title": "Fabric weight and edge behavior"}, {"id": "16c97669-d0fe-4f0b-9bd2-81c9b3005c4a", "type": "concept", "title": "Light across folds"}], "description": "Students learn to draw cloth as gravity, fold, compression, and tension."}]}, {"id": "ecad4da2-7896-428a-b8d6-ad00c8e23a44", "type": "topic", "title": "Experimental Drawing, Abstraction, and Concept", "description": "Foundation drawing should build skill and imagination. This topic opens drawing beyond accuracy into process, invention, abstraction, and conceptual thinking.", "children": [{"id": "895d0f49-a2de-42bd-905a-33c9ce37dd8d", "type": "subtopic", "title": "Experimental mark-making", "children": [{"id": "8e745e43-6300-4422-b2c4-718c01a35674", "type": "concept", "title": "Nontraditional tools and surfaces"}, {"id": "ab90186a-2585-44e6-8ffe-27cf2bc0944d", "type": "concept", "title": "Chance, repetition, and constraint"}, {"id": "2869afcf-05f4-49b1-893e-2bc394875c1e", "type": "concept", "title": "Scale shifts and bodily movement"}], "description": "Students test drawing as exploration rather than only representation."}, {"id": "829729a0-ecc4-4e6f-804f-1efdb19276cd", "type": "subtopic", "title": "Abstraction from observation", "children": [{"id": "9c0d4910-bf8d-4db1-bd3b-d447a6c8186b", "type": "concept", "title": "Simplification and exaggeration"}, {"id": "4bc46f05-9ee3-476a-8cad-f059c282e877", "type": "concept", "title": "Pattern, grid, and fragmentation"}, {"id": "bf7ef7e7-6144-4c91-b87c-beeb6d5d2671", "type": "concept", "title": "From representational study to abstract composition"}], "description": "This subtopic teaches students to transform what they see into structure, rhythm, and concept."}, {"id": "510c1ffd-6ef5-4fe7-82ac-71cd1dd11543", "type": "subtopic", "title": "Drawing as idea development", "children": [{"id": "7e191713-89c2-4a61-a0ea-a53e36a0c666", "type": "concept", "title": "Diagramming and visual notes"}, {"id": "404f3b9c-2e60-4617-a29a-48d9ad6b2222", "type": "concept", "title": "Sequential studies and variations"}, {"id": "4d196bb7-96b1-46e9-8b46-a4a148e7fc6f", "type": "concept", "title": "Drawing as research and proposal"}], "description": "Students use drawing to think, not just to render."}]}, {"id": "bb7f6e22-9e77-480b-9ba0-b030d8255448", "type": "topic", "title": "Sketchbook Practice and Visual Research", "description": "The sketchbook is a laboratory for attention, memory, research, and personal voice. Students learn to use it daily and intentionally.", "children": [{"id": "bbfb240d-75ac-4e83-b835-e671718cca67", "type": "subtopic", "title": "Daily sketchbook routines", "children": [{"id": "a43c2f9d-b5a1-48dc-afa4-be8c366bd1da", "type": "concept", "title": "Observation pages"}, {"id": "0275dc68-adb6-4831-99c9-7002c771be01", "type": "concept", "title": "Memory and imagination prompts"}, {"id": "1946aa22-80b4-472f-b843-9296d3cedcc5", "type": "concept", "title": "Date, annotate, and reflect"}], "description": "Students build volume, resilience, and curiosity through regular practice."}, {"id": "35e7e3c5-d4fe-4c2e-bc08-31b731fc89a8", "type": "subtopic", "title": "Visual research and artist precedents", "children": [{"id": "59da96d6-7ba6-485f-8f73-bfdd448abfca", "type": "concept", "title": "Copying as study with attribution"}, {"id": "3acea41e-5f58-4a87-b783-00331983a3ed", "type": "concept", "title": "Artist lineage maps"}, {"id": "7160db0f-44de-4d44-a8b6-d401750b2eda", "type": "concept", "title": "Museum, street, studio, and digital research"}], "description": "This subtopic connects drawing practice to art, design, illustration, architecture, and contemporary practice."}, {"id": "d68b084a-b11b-4275-99c4-34c4eaad3d1e", "type": "subtopic", "title": "Idea development", "children": [{"id": "b2484c97-d4f9-4a0d-b8c5-771eb38fa555", "type": "concept", "title": "Lists, thumbnails, and variations"}, {"id": "e592d4e6-6c20-425a-9c89-b0fcc3fd66b4", "type": "concept", "title": "Combining reference and imagination"}, {"id": "39c8adf8-2812-47b0-a009-60914eb06059", "type": "concept", "title": "Selecting and revising promising directions"}], "description": "Students learn to move from scattered sketches to stronger projects."}]}, {"id": "84b0e240-9563-4e59-aa54-0727a04dbb1a", "type": "topic", "title": "Digital Support, Documentation, and Hybrid Drawing", "description": "Foundation drawing remains materially grounded, but digital tools can support documentation, critique, iteration, and hybrid workflows.", "children": [{"id": "2dfe34e9-76c8-42a1-936b-ef2f16d95ed6", "type": "subtopic", "title": "Documenting drawings", "children": [{"id": "937aca2d-b952-44e2-ac29-a087399d1961", "type": "concept", "title": "Lighting, alignment, and resolution"}, {"id": "ded060a9-70ad-4fec-a1bb-2b511ec13a3e", "type": "concept", "title": "File naming and process archive"}, {"id": "64c42213-e5e0-4c90-b2b5-163f97cd8cad", "type": "concept", "title": "Before-after revision documentation"}], "description": "Students learn to photograph, scan, crop, color-correct, and archive work responsibly."}, {"id": "96f4f27e-1f6d-4d20-afb7-4eec2debc66b", "type": "subtopic", "title": "Digital drawing support", "children": [{"id": "11eae920-9fab-49e1-adff-da65ad5e3bae", "type": "concept", "title": "Layering, opacity, and value studies"}, {"id": "ebb03eaf-6350-4188-b13d-b1712c5e36ed", "type": "concept", "title": "Digital thumbnails and compositional tests"}, {"id": "f4d39361-8399-4d1a-9102-ca21fe6645fd", "type": "concept", "title": "Tablet ergonomics and limitations"}], "description": "This subtopic introduces digital tools as extensions of practice rather than shortcuts."}, {"id": "65a964dd-ff3a-4843-9aa8-3f33774d6d68", "type": "subtopic", "title": "Hybrid workflows", "children": [{"id": "3a8594e5-fbb4-4f89-9a5c-99d2d405384d", "type": "concept", "title": "Scanning and reworking drawings"}, {"id": "2e94b873-55f1-428c-9ee7-7f72e3b320ee", "type": "concept", "title": "Print, trace, transfer, and collage"}, {"id": "82c52789-ba99-40f9-89a9-f0a79cc31e50", "type": "concept", "title": "Portfolio-ready presentation files"}], "description": "Students combine analog and digital methods while preserving material learning."}]}, {"id": "7e20064a-3167-4dee-b679-00c5db491ed3", "type": "topic", "title": "Critique, Revision, and Reflective Practice", "description": "World-class foundation drawing teaches students 