values
  ('168aab50-85de-4195-8e35-62b0402e37bb', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', null, 'topic'::public.curated_course_node_type, 'Studio Culture, Materials, Tools, and Drawing Habits', 'Foundation drawing begins with disciplined studio habits. Students learn how materials behave, how to set up a workspace, and how regular practice turns observation into skill.', 0),
  ('77bf2f79-12e5-48a8-adbc-7dd1d7cd530e', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '168aab50-85de-4195-8e35-62b0402e37bb', 'subtopic'::public.curated_course_node_type, 'Drawing materials and surfaces', 'Students learn what different tools do and why tool choice affects mark, value, speed, and revision.', 0),
  ('b9c37d4e-73da-4569-ac4a-dbc48c7da1d5', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '77bf2f79-12e5-48a8-adbc-7dd1d7cd530e', 'concept'::public.curated_course_node_type, 'Graphite, charcoal, conte, ink, eraser, and blending tools', null, 0),
