  ('3766b009-71f7-4271-aec7-9818d1922053', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '168aab50-85de-4195-8e35-62b0402e37bb', 'subtopic'::public.curated_course_node_type, 'Studio process and practice rhythm', 'This subtopic builds reliable habits for showing up, warming up, and sustaining attention.', 1),
