  ('a4ae7914-c264-4b03-a6bb-b3f6ca8d11de', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '3766b009-71f7-4271-aec7-9818d1922053', 'concept'::public.curated_course_node_type, 'Process notes, dates, and reflection', null, 2),
  ('0efe386a-01b2-4e40-84b6-ee94eec35c56', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '168aab50-85de-4195-8e35-62b0402e37bb', 'subtopic'::public.curated_course_node_type, 'Foundation critique norms', 'Students learn how to talk about drawings with specificity and care.', 2),
