  ('3fc3aae3-d970-40ac-9a3f-7977676351ac', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '0efe386a-01b2-4e40-84b6-ee94eec35c56', 'concept'::public.curated_course_node_type, 'Intent, effect, and evidence', null, 1),
  ('19a0a251-67b9-4a2c-a88c-d0687c4a289b', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '0efe386a-01b2-4e40-84b6-ee94eec35c56', 'concept'::public.curated_course_node_type, 'Receiving feedback and setting revision goals', null, 2),
  ('23cf3ef4-c2e1-446e-b6d0-658a8f4621a4', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', null, 'topic'::public.curated_course_node_type, 'Seeing, Measuring, and Observational Discipline', 'Drawing I is mainly about learning to see. Students practice slowing down, comparing, measuring, and correcting what they think they see against what is actually present.', 1),
  ('74a53073-acd0-4490-9ae1-290e53031810', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '23cf3ef4-c2e1-446e-b6d0-658a8f4621a4', 'subtopic'::public.curated_course_node_type, 'Perceptual observation', 'Students learn to suspend symbolic shortcuts and attend to actual visual relationships.', 0),
  ('31b03ae4-3a51-4c02-b337-cd8dbf213ecf', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '74a53073-acd0-4490-9ae1-290e53031810', 'concept'::public.curated_course_node_type, 'Edges, angles, intervals, and alignments', null, 0),
  ('a2ede1f3-03a1-4c1b-ba87-68a8f46f939b', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '74a53073-acd0-4490-9ae1-290e53031810', 'concept'::public.curated_course_node_type, 'Negative space and shape relationships', null, 1),
  ('3a9523b3-b498-4993-bdf7-f8fdde9760aa', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '74a53073-acd0-4490-9ae1-290e53031810', 'concept'::public.curated_course_node_type, 'Visual checking and self-correction', null, 2),
  ('d672b6e6-6435-4405-b2cb-efd9a832a9e9', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '23cf3ef4-c2e1-446e-b6d0-658a8f4621a4', 'subtopic'::public.curated_course_node_type, 'Sighting and proportion', 'This subtopic teaches practical measuring methods that support accurate observation.', 1),
  ('378a833f-2a80-48bb-a592-ad6173904017', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd672b6e6-6435-4405-b2cb-efd9a832a9e9', 'concept'::public.curated_course_node_type, 'Plumb lines and level lines', null, 0),
  ('61bb2c0c-0621-4b30-905b-9f628f554ab9', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd672b6e6-6435-4405-b2cb-efd9a832a9e9', 'concept'::public.curated_course_node_type, 'Comparative measurement', null, 1),
  ('6eae00f6-451f-44c3-9643-06a07149bae3', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd672b6e6-6435-4405-b2cb-efd9a832a9e9', 'concept'::public.curated_course_node_type, 'Proportion, scale, and relational drawing', null, 2),
  ('d5180ea7-9dc8-49a8-9c32-c9c71ed3e76e', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '23cf3ef4-c2e1-446e-b6d0-658a8f4621a4', 'subtopic'::public.curated_course_node_type, 'Drawing from simple objects', 'Students build accuracy through still-life structures before moving to complex subjects.', 2),
  ('8e15c28b-22e0-42d3-9156-a06e4c6b2938', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd5180ea7-9dc8-49a8-9c32-c9c71ed3e76e', 'concept'::public.curated_course_node_type, 'Boxes, cylinders, spheres, and organic forms', null, 0),
  ('df2bbdd7-93ca-4b93-8bf4-8dbd70b29aeb', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd5180ea7-9dc8-49a8-9c32-c9c71ed3e76e', 'concept'::public.curated_course_node_type, 'Object placement and eye level', null, 1),
  ('d6ff132e-b9a0-4106-8831-63505f90f3ca', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd5180ea7-9dc8-49a8-9c32-c9c71ed3e76e', 'concept'::public.curated_course_node_type, 'Simple-to-complex observation sequences', null, 2),
  ('5096e4a7-a95c-48c9-86da-cc8bf5c61e6e', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', null, 'topic'::public.curated_course_node_type, 'Line Quality, Contour, and Edge', 'Line is both a record of looking and a design element. Students learn to use line with confidence, sensitivity, hierarchy, and expressive control.', 2),
  ('2d15213d-60db-440a-b3e5-6b81232d14b9', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '5096e4a7-a95c-48c9-86da-cc8bf5c61e6e', 'subtopic'::public.curated_course_node_type, 'Line control', 'Students develop physical control through repeated marks and varied pressure.', 0),
  ('01fd48c1-5616-4bd9-bc11-113c18109883', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '2d15213d-60db-440a-b3e5-6b81232d14b9', 'concept'::public.curated_course_node_type, 'Straight, curved, tapered, and weighted lines', null, 0),
  ('6aabd05f-0585-4a3f-9e86-21a5b62eaf2c', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '2d15213d-60db-440a-b3e5-6b81232d14b9', 'concept'::public.curated_course_node_type, 'Speed, pressure, rhythm, and confidence', null, 1),
  ('f6695390-e4a3-4c84-9948-8a89615fecdb', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '2d15213d-60db-440a-b3e5-6b81232d14b9', 'concept'::public.curated_course_node_type, 'Ghosting, overhand grip, and arm movement', null, 2),
  ('d001d63b-e7aa-4f01-8a0f-383cf68489bd', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '5096e4a7-a95c-48c9-86da-cc8bf5c61e6e', 'subtopic'::public.curated_course_node_type, 'Contour drawing', 'Contour studies teach students to follow edges carefully and coordinate hand, eye, and attention.', 1),
  ('17af105d-7da5-48c2-8b5a-d2f7684281aa', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd001d63b-e7aa-4f01-8a0f-383cf68489bd', 'concept'::public.curated_course_node_type, 'Blind contour', null, 0),
  ('bcd18bd9-7ef8-4a79-91b6-d98b620bfb18', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd001d63b-e7aa-4f01-8a0f-383cf68489bd', 'concept'::public.curated_course_node_type, 'Modified contour', null, 1),
  ('c1a31539-a24b-443c-944f-2c3b001d1fb5', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd001d63b-e7aa-4f01-8a0f-383cf68489bd', 'concept'::public.curated_course_node_type, 'Cross-contour and form wrapping', null, 2),
  ('cf30046b-b4b1-4f1c-ac58-64a9f61397d6', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', '5096e4a7-a95c-48c9-86da-cc8bf5c61e6e', 'subtopic'::public.curated_course_node_type, 'Edge hierarchy', 'Students learn that edges can be hard, soft, lost, found, light, heavy, active, or quiet.', 2),
  ('ce8647d5-f969-4072-87c2-391baae72883', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'cf30046b-b4b1-4f1c-ac58-64a9f61397d6', 'concept'::public.curated_course_node_type, 'Line weight and spatial depth', null, 0),
  ('793a133e-651a-40b7-8d25-ce6899b52a16', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'cf30046b-b4b1-4f1c-ac58-64a9f61397d6', 'concept'::public.curated_course_node_type, 'Overlaps and contact points', null, 1),
  ('4b9765b6-5e6d-4d44-9966-f624d6f0e43d', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'cf30046b-b4b1-4f1c-ac58-64a9f61397d6', 'concept'::public.curated_course_node_type, 'Edges as design and emphasis', null, 2),
  ('e8591a49-0771-41fa-88f5-461244eb0754', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', null, 'topic'::public.curated_course_node_type, 'Shape, Negative Space, and Notan', 'Before form becomes convincing, shape must be organized clearly. This topic teaches students to see silhouettes, intervals, and value masses as design structures.', 3);
