  ('0a0f8cd7-1c82-4bf2-8164-306dc19d461a', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'e2426e79-f5c4-4ddf-8c8b-ba9b129baf6d', 'concept'::public.curated_course_node_type, 'Balance, tension, and asymmetry', null, 1),
  ('4b799aa6-0b7a-4bd9-ba8c-bd171670acb3', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'e2426e79-f5c4-4ddf-8c8b-ba9b129baf6d', 'concept'::public.curated_course_node_type, 'Focal area and visual path', null, 2),
