  ('abbb9071-1e1a-45df-b462-90d1d4183379', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'a2d397ff-bcda-4a3e-80a9-ea7f1bc0e830', 'concept'::public.curated_course_node_type, 'Value scales and swatches', null, 0),
