  ('3dd6a940-5896-4ffd-b239-73d10b01d5f6', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'a2d397ff-bcda-4a3e-80a9-ea7f1bc0e830', 'concept'::public.curated_course_node_type, 'High key, low key, and full range', null, 2),
