  ('75c3fe81-84f1-4f40-b606-d6d66be9f219', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'd6af667d-d10e-4741-ab33-fec27af07620', 'concept'::public.curated_course_node_type, 'Direction, rhythm, and surface', null, 2),
