  ('fdbf14f2-7fd9-472d-a6c6-a2fa1b0268f3', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'dadf7e2b-51af-4d9a-9258-429aecb64e5b', 'concept'::public.curated_course_node_type, 'Grouping shadows', null, 0),
  ('49101e1b-b434-4bf9-b8cc-dc4fe3adca5d', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'dadf7e2b-51af-4d9a-9258-429aecb64e5b', 'concept'::public.curated_course_node_type, 'Separating planes', null, 1),
  ('dceb82f4-aabb-4d0c-9bf5-178e87943dc2', 'e5f6a7b8-9c0d-4e57-8b67-7c8d9e0f1a37', 'dadf7e2b-51af-4d9a-9258-429aecb64e5b', 'concept'::public.curated_course_node_type, 'Controlling emphasis through contrast', null, 2),
